$pdo=Database::getConnection();$_SESSION['billing_schedule_csrf']=$_SESSION['billing_schedule_csrf']??bin2hex(random_bytes(32));$guard=new ChantierCreationGuardService($pdo);$devisId=(int)($_GET['devis_id']??$_POST['devis_id']??0);$chantierId=(int)($_GET['chantier_id']??$_POST['chantier_id']??0);$message='';$error='';
$stmt=$pdo->prepare('SELECT d.id,d.numero_devis,d.total_ttc,d.date_emission,d.project_start_date,d.project_end_date,c.id chantier_id,c.code,c.titre FROM devis_banamur d JOIN chantier_banamur c ON c.devis_id=d.id AND c.archived_at IS NULL WHERE d.id=:devis AND (:chantier=0 OR c.id=:chantier) LIMIT 1');$stmt->execute(['devis'=>$devisId,'chantier'=>$chantierId]);$row=$stmt->fetch(PDO::FETCH_ASSOC);if(!$row){http_response_code(404);exit('Devis ou chantier actif introuvable.');}$chantierId=(int)$row['chantier_id'];
