if($_SERVER['REQUEST_METHOD']==='POST')try{$schedule=json_decode((string)($_POST['schedule_json']??'[]'),true);if(!is_array($schedule))throw new DomainException('Échéancier invalide.');$guard->savePreparation($devisId,(string)$row['project_start_date'],(string)$row['project_end_date'],$schedule);(new ChantierFinancialComplianceService($pdo))->auditOne($chantierId,$devisId);$message='Échéancier enregistré. Les prévisions de facturation sont maintenant actualisées.';}catch(Throwable $e){$error=$e->getMessage();}$schedule=$guard->schedule($devisId);
