put type="hidden" name="schedule_json" id="scheduleJson"><div id="rows" class="space-y-3"></div><div class="mt-4 flex justify-between rounded-xl bg-slate-100 p-4 font-black"><span>Total planifié</span><span id="total">0 %</span></div><div class="mt-6 flex flex-wrap gap-3"><button class="rounded-xl bg-indigo-700 px-5 py-3 font-black text-white" <?=empty($row['project_start_date'])||empty($row['project_end_date'])?'disabled':''?>><i class="fas fa-save mr-2"></i>Enregistrer l’échéancier</button><a href="factures_vente.php?chantier_id=<?=$chantierId?>#nouvelle-facture" class="rounded-xl border px-5 py-3 font-bold">Créer une facture réelle</a><a href="../chantiers/rapport_regularisation.php" class="rounded-xl border px-5 py-3 font-bold">Retour au rapport</a></div></form></section></div></main>
<script>(()=>{const initial=<?=json_encode($schedule,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)?>,amount=<?=json_encode((float)$row['total_ttc'])?>,emission=<?=json_encode((string)$row['date_emission'])?>,rows=document.getElementById('rows'),json=document.getElementById('scheduleJson'),total=document.getElementById('total');function refresh(){const data=[...rows.children].map(r=>({label:r.querySelector('[data-label]').value.trim(),expected_date:r.querySelector('[data-date]').value,percentage:Number(r.querySelector('[data-pct]').value)||0})),sum=data.reduce((s,r)=>s+r.percentage,0);[...rows.children].forEach(r=>r.querySelector('[data-amount]').textContent=new Intl.NumberFormat('fr-FR',{maximumFractionDigits:0}).format(amount*(Number(r.querySelector('[data-pct]').value)||0)/100)+' FCFA');total.textContent=sum.toLocaleString('fr-FR',{maximumFractionDigits:2})+' %';total.className=Math.abs(sum-100)<.01?'text-emerald-700':'text-rose-700';json.value=JSON.stringify(data)}function add(v={}){const r=document.createElement('div');r.className='grid gap-3 rounded-xl border p-4 md:grid-cols-[1fr_170px_120px_150px_40px]';r.innerHTML=`<input data-label required placeholder="Ex. Acompte" class="rounded-lg border px-3 py-2" value="${String(v.label||'').replace(/"/g,'&quot;')}"><input data-date required type="date" min="${emission}" class="rounded-lg border px-3 py-2" value="${v.expected_date||''}"><input data-pct required type="number" min=".01" max="100" step=".01" placeholder="%" class="rounded-lg border px-3 py-2" value="${v.percentage||''}"><strong data-amount class="self-center text-right text-sm">0 FCFA</strong><button type="button" class="text-xl font-black text-rose-600">×</button>`;r.querySelector('button').onclick=()=>{r.remove();refresh()};r.querySelectorAll('input').forEach(i=>i.oninput=refresh);rows.appendChild(r);refresh()}(initial.length?initial:[{label:'Acompte',percentage:50},{label:'Solde',percentage:50}]).forEach(add);document.getElementById('addRow').onclick=()=>add();document.getElementById('scheduleForm').onsubmit=e=>{refresh();if(Math.abs([...rows.querySelectorAll('[data-pct]')].reduce((s,i)=>s+(Number(i.value)||0),0)-100)>.01){e.preventDefault();alert('L’échéancier doit totaliser exactement 100 %.')}}})();</script>
